<script setup lang="ts">
import { listenAsApp } from '../bus';
import { computed, getCurrentInstance, inject, nextTick, onBeforeUnmount, ref } from 'vue';
import { VISION } from '../vision';
import { vHover } from '../kit/hover';
import { PLACES, CONDITIONS, forecast, type ForecastDay } from './weather/model';
import Sky from './weather/Sky.vue';
import WeatherIcon from './weather/WeatherIcon.vue';
import CityList from './weather/CityList.vue';
import Radar from './weather/Radar.vue';
import AppSheet from './arcade/AppSheet.vue';
defineProps<{ compact?: boolean }>();
const vision = inject(VISION)!;
const selected = ref('bengaluru');
const fahrenheit = ref(false);
const placesOpen = ref(false);
const page = ref<'Overview' | '10-Day' | 'Details'>('Overview');
const radarOpen = ref(false);
const pages = ['Overview', '10-Day', 'Details'] as const;
const wet = computed(() => ['rain', 'snow', 'storm'].includes(city.value.condition));
const chartHours = computed(() => data.value.hours.slice(0, 12));
const chartPoints = computed(() => chartHours.value.map((h, i) => (20 + i * 48) + ',' + (42 - (h.temp - data.value.low) / Math.max(1, data.value.high - data.value.low) * 32)).join(' '));
const moonIllumination = computed(() => Math.round((.5 - .5 * Math.cos((now.value.getTime() / 86400000 - 10962.6) / 29.53059 * Math.PI * 2)) * 100));
const moonPhase = computed(() => moonIllumination.value > 95 ? 'Full moon' : moonIllumination.value < 5 ? 'New moon' : moonIllumination.value > 50 ? 'Gibbous moon' : 'Crescent moon');
const minute = computed(() => Math.floor(vision.now.value.getTime() / 60000));
const now = computed(() => new Date(minute.value * 60000));
const city = computed(() => PLACES.find(place => place.id === selected.value) ?? PLACES[0]!);
const data = computed(() => forecast(city.value, now.value));
const minimum = computed(() => Math.min(...data.value.days.map(day => day.low)));
const maximum = computed(() => Math.max(...data.value.days.map(day => day.high)));
const daylight = computed(() => Math.max(0, Math.min(1, (data.value.hour - data.value.sunrise) / (data.value.sunset - data.value.sunrise))));
const sunPoint = computed(() => ({ x: 100 - 84 * Math.cos(Math.PI * daylight.value), y: 90 - 60 * Math.sin(Math.PI * daylight.value) }));
const uvName = computed(() => data.value.uv < 3 ? 'Low' : data.value.uv < 6 ? 'Moderate' : data.value.uv < 8 ? 'High' : 'Very high');
const airName = computed(() => data.value.aqi <= 50 ? 'Good' : 'Moderate');
function temp(value: number): string { return Math.round(fahrenheit.value ? value * 9 / 5 + 32 : value) + '°'; }
function range(day: ForecastDay): Record<string, string> { return { left: position(day.low) + '%', width: (day.high - day.low) / (maximum.value - minimum.value || 1) * 100 + '%' }; }
function position(value: number): number { return (value - minimum.value) / (maximum.value - minimum.value || 1) * 100; }
function select(id: string): void { selected.value = id; placesOpen.value = false; }
function sheetKeys(event:KeyboardEvent):void { if(event.key==='Escape' && (placesOpen.value || radarOpen.value)) { event.stopPropagation(); placesOpen.value=false; radarOpen.value=false; } }
function sunTime(hour: number): string { const h = Math.floor(hour); return String(h).padStart(2, '0') + ':' + String(Math.round((hour - h) * 60)).padStart(2, '0'); }

const jarvisInstance = getCurrentInstance();
function jarvisName(value: string): string {
  return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\b(the|my)\b/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
}
// JARVIS can work in Weather: show, hourly, week.
const stopJarvis = listenAsApp('weather', async command => {
  let line = "I can't do that in Weather yet.";
  try {
    switch (command.action === 'do' ? command.verb : '') {
      case 'show': {
        const term = jarvisName(String(command.arg ?? ''));
        const place = term ? PLACES.find(item => jarvisName(item.name) === term)
          ?? PLACES.find(item => jarvisName(item.name).includes(term)) : undefined;
        if (place) { radarOpen.value = false; select(place.id); line = 'Showing the weather in ' + place.name + '.'; }
        else line = 'Available cities are ' + PLACES.map(item => item.name).join(', ') + '.';
        break;
      }
      case 'hourly':
      case 'week': {
        placesOpen.value = false; radarOpen.value = false;
        page.value = command.verb === 'hourly' ? 'Overview' : '10-Day';
        await nextTick();
        const root = jarvisInstance?.proxy?.$el as HTMLElement | undefined;
        root?.querySelector(command.verb === 'hourly' ? '.hourly' : '.daily')?.scrollIntoView({ block: 'nearest' });
        line = 'Showing the ' + (command.verb === 'hourly' ? 'hourly' : '10-day') + ' forecast for ' + city.value.name + '.';
        break;
      }
    }
  } catch { line = "I couldn't complete that in Weather."; }
  try { (command.reply as ((line: string) => void) | undefined)?.(line); } catch { /* The caller owns its reply callback. */ }
});
onBeforeUnmount(() => stopJarvis());
</script>

<template>
<div class="weather-app" :class="{ compact, solid:vision.reduceTransparency.value }" aria-label="Weather demo" @keydown="sheetKeys">
<Sky :condition="city.condition" :hour="data.hour" :seed="city.seed"/>
<div class="weather-layout" :inert="placesOpen || radarOpen ? true : undefined">
<aside class="sidebar vk-platter"><header><h1 class="vk-title">Weather</h1><span class="vk-footnote vk-secondary">My places</span></header><CityList :selected="selected" :now="now" :fahrenheit="fahrenheit" @select="select"/></aside>
<main class="forecast"><header class="forecast-toolbar"><button v-hover class="vk-icon places-button" aria-label="Choose a place" @click="placesOpen=true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/></svg></button><div class="vk-segmented page-tabs" role="group" aria-label="Weather view"><button v-for="item in pages" :key="item" v-hover :aria-pressed="page===item" @click="page=item">{{ item }}</button></div><div class="vk-segmented units" aria-label="Temperature units"><button v-hover :aria-pressed="!fahrenheit" @click="fahrenheit=false">°C</button><button v-hover :aria-pressed="fahrenheit" @click="fahrenheit=true">°F</button></div></header>
<div class="forecast-content vk-scroll" :key="selected+'-'+page">
<template v-if="page==='Overview'"><div class="overview-top"><section class="weather-hero"><div><p class="region vk-footnote">{{ city.region }} <span>· Demo forecast</span></p><h2>{{ city.name }}</h2><p class="condition">{{ CONDITIONS[city.condition] }}</p><p class="high-low">H:{{ temp(data.high) }} · L:{{ temp(data.low) }}</p></div><div class="temperature">{{ temp(data.current) }}</div></section><button v-hover class="radar-open" aria-label="Open illustrative precipitation map" @click="radarOpen=true"><Radar :city="city.name" :wet="wet"/></button></div>
<section class="hourly panel vk-platter"><header class="panel-heading"><p class="panel-title">HOURLY FORECAST</p><span class="vk-footnote vk-secondary">{{ wet ? 'Rain continues this evening' : 'A clear outlook ahead' }}</span></header><div class="hour-chart vk-scroll" tabindex="0" aria-label="Scrollable hourly temperatures"><svg class="temperature-chart" viewBox="0 0 568 48" role="img" aria-label="Hourly temperature trend"><path d="M20 44h528M20 10h528" stroke="#ffffff16" stroke-dasharray="3 5"/><polyline :points="chartPoints + ' 548,48 20,48'" fill="#b8dff411"/><polyline :points="chartPoints" fill="none" stroke="#c1e5fc" stroke-width="2" stroke-linejoin="round"/><circle v-for="(hour,i) in chartHours" :key="hour.key" :cx="20+i*48" :cy="42-(hour.temp-data.low)/Math.max(1,data.high-data.low)*32" r="3" fill="#dcf2ff"/></svg><div class="chart-labels"><div v-for="hour in chartHours" :key="hour.key"><strong>{{ temp(hour.temp) }}</strong><WeatherIcon :condition="hour.condition" :night="hour.hour<6 || hour.hour>=19"/><span>{{ hour.label }}</span><small>{{ hour.precipitation }}%</small></div></div></div></section>
<div class="overview-highlights"><button v-hover class="highlight vk-platter" @click="page='Details'"><span>FEELS LIKE</span><strong>{{ temp(data.feels) }}</strong><small>{{ data.feels===data.current ? 'Similar to actual temperature' : 'Humidity and wind considered' }}</small></button><button v-hover class="highlight vk-platter" @click="page='Details'"><span>AIR QUALITY</span><strong>{{ data.aqi }} <i>{{ airName }}</i></strong><div class="spectrum air"><b :style="{left:data.aqi/150*100+'%'}"/></div></button><button v-hover class="highlight vk-platter" @click="page='10-Day'"><span>TOMORROW</span><strong>{{ temp(data.days[1]!.high) }} <WeatherIcon :condition="data.days[1]!.condition"/></strong><small>Low {{ temp(data.days[1]!.low) }} · 10-day forecast</small></button></div><p class="overview-note">Generated forecast · Explore details for wind, UV, moon phase and more.</p></template>
<section v-else-if="page === '10-Day'" class="panel daily vk-platter" aria-label="10-day demo forecast"><p class="panel-title">10-DAY FORECAST</p><div v-for="(day,index) in data.days" :key="day.key" class="day"><strong>{{ day.label }}</strong><div class="day-condition"><WeatherIcon :condition="day.condition" /><small v-if="day.precipitation > 20">{{ day.precipitation }}%</small></div><span class="vk-secondary">{{ temp(day.low) }}</span><div class="range-track" role="img" :aria-label="day.label + ': low ' + temp(day.low) + ', high ' + temp(day.high)"><i :style="range(day)" /><b v-if="index === 0" :style="{ left: position(data.current) + '%' }" /></div><span>{{ temp(day.high) }}</span></div></section>

<div v-else class="metrics">
        <section class="metric panel vk-platter"><p class="panel-title">UV INDEX</p><strong class="metric-value">{{ data.uv }}</strong><h3>{{ uvName }}</h3><div class="spectrum uv"><i :style="{ left: data.uv / 11 * 100 + '%' }" /></div><p>{{ data.uv >= 3 ? 'Sunscreen: yes. Excuses: no.' : 'The sun is keeping things gentle.' }}</p></section>
        <section class="metric wind panel vk-platter"><p class="panel-title">WIND</p><div class="wind-body"><div><strong class="metric-value">{{ data.wind }}</strong><small>km/h</small></div><svg viewBox="0 0 120 120" class="compass" role="img" :aria-label="'Wind from ' + data.bearing + ' degrees'"><circle cx="60" cy="60" r="44" fill="none" stroke="#ffffff30" stroke-dasharray="1 5" /><text x="60" y="13">N</text><text x="108" y="64">E</text><text x="60" y="117">S</text><text x="12" y="64">W</text><g :transform="'rotate(' + data.bearing + ' 60 60)'" fill="none" stroke="#d1eeff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M60 90V30m-9 12 9-12 9 12" /><circle cx="60" cy="60" r="4" fill="#e7f5ff" /></g></svg></div><p>Hair with a plot twist.</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">HUMIDITY</p><strong class="metric-value">{{ data.humidity }}<small>%</small></strong><div class="humidity-drops" aria-hidden="true"><svg v-for="i in 8" :key="i" viewBox="0 0 12 18" :class="{ filled: i <= Math.round(data.humidity / 12.5) }"><path d="M6 1C6 1 1 8 1 11a5 5 0 0 0 10 0C11 8 6 1 6 1Z" /></svg></div><p>Dew point {{ temp(data.dew) }}. The air is feeling clingy.</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">SUNRISE & SUNSET</p><div class="sun-times"><strong>{{ sunTime(data.sunrise) }}</strong><strong>{{ sunTime(data.sunset) }}</strong></div><svg class="sun-arc" viewBox="0 0 200 105" role="img" :aria-label="'Sunrise ' + sunTime(data.sunrise) + ', sunset ' + sunTime(data.sunset)"><path d="M16 90C16 10 184 10 184 90" fill="none" stroke="#fff2a95c" stroke-width="2" /><path d="M6 90h188" stroke="#ffffff40" stroke-dasharray="3 4" /><path d="M16 90a84 60 0 0 1 168 0" fill="none" stroke="#ffe5aa" stroke-width="2" /><circle :cx="sunPoint.x" :cy="sunPoint.y" r="7" fill="#ffe5aa" /></svg><p>{{ data.hour < data.sunrise || data.hour > data.sunset ? 'The sun has clocked out. You may too.' : 'A daily show. No ticket required.' }}</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">FEELS LIKE</p><strong class="metric-value">{{ temp(data.feels) }}</strong><h3>{{ data.feels === data.current ? 'Just as it looks' : data.feels < data.current ? 'A little cooler' : 'A little warmer' }}</h3><p>Your sleeves may have an opinion.</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">AIR QUALITY</p><strong class="metric-value">{{ data.aqi }}</strong><h3>{{ airName }} <small>· Demo AQI</small></h3><div class="spectrum air"><i :style="{ left: data.aqi / 150 * 100 + '%' }" /></div><p>{{ airName === 'Good' ? 'A fictional deep breath of fresh air.' : 'Even imaginary air has its off days.' }}</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">VISIBILITY</p><strong class="metric-value">{{ data.visibility }}<small>km</small></strong><svg class="visibility-lines" viewBox="0 0 180 40" fill="none" stroke="#ffffff60" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M5 32h170M25 22h130M45 12h90M65 2h50" /></svg><p>{{ data.visibility < 5 ? 'The horizon pressed the snooze button.' : 'The horizon is accepting visitors.' }}</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">PRESSURE</p><div class="pressure"><svg viewBox="0 0 160 90" aria-hidden="true"><path d="M15 80a65 65 0 0 1 130 0" fill="none" stroke="#ffffff40" stroke-width="9" stroke-dasharray="2 5" /><path d="M80 80V25" :transform="'rotate(' + ((data.pressure - 1010) * 3) + ' 80 80)'" stroke="#deedff" stroke-width="2" stroke-linecap="round" /><circle cx="80" cy="80" r="5" fill="#deedff" /></svg><strong>{{ data.pressure }} <small>hPa</small></strong></div><p>Under pressure. Still quite composed.</p></section>
        <section class="metric panel vk-platter moon-card"><p class="panel-title">MOON PHASE</p><div class="moon-body"><span class="moon-orb" :style="{'--moon':moonIllumination/100}" aria-hidden="true"/><div><strong>{{ moonIllumination }}%</strong><h3>{{ moonPhase }}</h3></div></div><p>Approximate lunar cycle illustration. Not an astronomical observation.</p></section>
      </div>

<footer v-if="page!=='Overview'" class="vk-footnote vk-secondary">Entirely generated demo data. No live weather service. City clocks use fixed UTC offsets; daylight saving changes are not applied.</footer>
</div></main></div>
<AppSheet v-if="placesOpen" title="Choose a place" @close="placesOpen=false"><CityList :selected="selected" :now="now" :fahrenheit="fahrenheit" @select="select"/></AppSheet>
<AppSheet v-if="radarOpen" title="Precipitation" @close="radarOpen=false"><Radar :city="city.name" :wet="wet" expanded/></AppSheet>
</div></template>
<style src="../kit/kit.css"></style>
<style scoped>
