.weather-app{font-family:-apple-system,BlinkMacSystemFont,'SF Pro Display','Segoe UI',sans-serif}.weather-layout{grid-template-columns:212px minmax(0,1fr)}.sidebar{padding:20px 10px;gap:18px}.sidebar header{padding:0 8px;display:grid;gap:4px}.sidebar h1{padding:0}.forecast{display:flex;flex-direction:column;min-height:0;padding:24px;gap:16px}.forecast-toolbar{flex:none}.page-tabs button{font-size:13px;padding:0 12px;min-height:44px}.forecast-content{flex:1;min-height:0;-webkit-mask-image:linear-gradient(to bottom,#000 calc(100% - 24px),transparent);mask-image:linear-gradient(to bottom,#000 calc(100% - 24px),transparent)}.overview-top{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(180px,1fr);gap:16px;margin-bottom:16px}.weather-hero{padding:12px 0;text-align:left;display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:166px}.weather-hero h2{font-size:31px;font-weight:600;margin:8px 0}.weather-hero .condition{font-size:16px;color:#e7f4ff;margin:0 0 8px}.temperature{font-size:86px;padding:0;flex:none;line-height:1}.high-low{font-size:13px;color:#e3f0ff}.region{font-size:12px}.region span{display:block;font-size:11.5px;margin-top:4px;color:#ffffff88}.radar-open{text-align:left;padding:0;background:none;color:inherit;border-radius:24px;min-width:0}.radar-open :deep(.radar){height:100%;box-sizing:border-box}.panel-heading{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:5px}.panel-heading .panel-title{margin:0}.panel-heading .vk-footnote{font-size:12px}.hour-chart{position:relative}.temperature-chart{height:48px;width:568px;display:block}.chart-labels{display:flex;width:568px;gap:0}.chart-labels>div{width:48px;flex:none;display:flex;align-items:center;flex-direction:column;gap:5px;font-size:12px}.chart-labels>div:first-child{width:44px}.chart-labels svg{width:24px;height:24px}.chart-labels strong{font-size:16px;font-weight:500}.chart-labels small{font-size:11.5px;color:#a9dfff}.hourly{margin-bottom:16px;padding:16px!important}.overview-highlights{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.highlight{display:flex;flex-direction:column;text-align:left;padding:16px;min-height:106px;gap:8px;color:inherit;background:#172f4c38}.highlight>span{font-size:11.5px;letter-spacing:.07em;color:#ffffffac}.highlight strong{font-size:29px;font-weight:400;display:flex;align-items:center;gap:8px}.highlight strong i{font-size:13px;font-style:normal;color:#bfe8d3}.highlight small{font-size:11.5px;color:#ffffffa8}.highlight strong svg{width:28px;height:28px}.highlight .spectrum{width:100%;margin:7px 0}.highlight .spectrum b{position:absolute;top:-2px;width:4px;height:9px;background:#fff;border-radius:3px}.overview-note{font-size:11.5px;color:#ffffff88;margin:16px 4px 0}.daily{padding:22px!important}.day{min-height:44px}.metrics{gap:14px}.moon-body{display:flex;align-items:center;gap:18px;margin:9px 0}.moon-body strong{font-size:30px;font-weight:400}.moon-orb{display:block;width:66px;height:66px;flex:none;border-radius:50%;background:radial-gradient(circle at 35% 25%,#ffffff30 0 5%,transparent 6%),radial-gradient(circle at 60% 63%,#ffffff20 0 12%,transparent 13%),#d6dcd6;box-shadow:inset calc((1 - var(--moon)) * -58px) 0 9px #14273d,0 0 24px #dcecff15}.solid .panel,.solid .highlight,.solid .sidebar{background:#26384d}
